 public static boolean known(ServerPlayer p,Catalog.Recipe r){return CraftState.data(p).value("known."+r.id(),0)>0||r.school().equals("medical")||(r.school().equals("fabricator")||r.school().equals("enhancer"))||(!r.role().equals("build")&&CraftState.knowledge(p,r.role())>=r.rank());}
 public static int grade(ServerPlayer p,String role){int n=0;for(var t:CraftState.data(p).templates()){String prefix="rpgtemplate:"+role+"_grade_";if(t.templateId().startsWith(prefix))try{n=Math.max(n,Integer.parseInt(t.templateId().substring(prefix.length())));}catch(Exception ignored){}}return Math.min(9,n);}
 public static void ensureProfessions(ServerPlayer p){if(!owner(p))return;var d=CraftState.data(p);if(d.value("craft.migration049",0)==0){CraftState.storage(p).m_128359_("backup048",d.toJsonString());JsonObject json=d.toJson();JsonArray templates=new JsonArray();for(JsonElement e:json.getAsJsonArray("templates")){String id=e.getAsJsonObject().get("id").getAsString();if(!id.matches("rpgtemplate:(build|smith|pharma)_grade_[1-9]"))templates.add(e);}for(String role:new String[]{"build","smith","pharma"}){int g=Math.max(1,grade(p,role));JsonObject t=new JsonObject();String id="rpgtemplate:"+role+"_grade_"+g;t.addProperty("id",id);t.addProperty("level",1);t.addProperty("xp",0);templates.add(t);if(d.loadedTemplateId()!=null&&d.loadedTemplateId().startsWith("rpgtemplate:"+role+"_grade_"))json.addProperty("loaded",id);}json.add("templates",templates);json.getAsJsonObject("values").addProperty("craft.migration049",1);p.getCapability(ModCapabilities.PLAYER_DATA).ifPresent(s->s.load(json.toString()));SystemDataManager.markDirty(p);}}
 public static int distinct(ServerPlayer p,String prefix,String role){int n=0;for(Catalog.Recipe r:Catalog.ALL)if(modern(r)&&r.role().equals(role)&&!r.aux()&&CraftState.data(p).value(prefix+r.id(),0)>0)n++;return n;}
 public static int pairs(ServerPlayer p){int n=0;for(int i=0;i<10;i++)if(CraftState.data(p).value("match."+i,0)>0)n++;int canonical=0;for(int i=0;i<30;i++)if(CraftState.data(p).value("canon.match."+i,0)>0)canonical++;return Math.max(n,canonical);}
 public static int discoveries(ServerPlayer p){int n=0;for(var b:BuildCatalog.CANON)if(CraftState.data(p).value("found."+b.id(),0)>0||CraftState.data(p).value("known.fullbottle_"+b.id(),0)>0||CraftState.data(p).value("made.fullbottle_"+b.id(),0)>0)n++;return n;}
 public static int batches(ServerPlayer p){int n=0;for(var b:BuildCatalog.ALL)if(CraftState.data(p).value("made.fullbottle_"+b.id(),0)>0)n++;return n+(int)CraftState.data(p).value("fabricator.success",0);}
 static final int[] BATCHES={1,3,6,10,15,20,25,30},SAMPLES={0,1,2,3,4,5,7,10};
 static final int[] DISCOVER={2,6,12,20,30,40,50,60},COMBOS={0,1,2,4,8,12,20,30};
 public static String task(ServerPlayer p,String role){int g=grade(p,role);if(g>=9)return "已达九品";if(g<1)return "无职业资格";if(!role.equals("build"))return "不同成品 "+distinct(p,"made.",role)+"/"+BuildRules.RESEARCH[g-1];return "发现 "+discoveries(p)+"/"+DISCOVER[g-1]+" · 合成 "+batches(p)+"/"+BATCHES[g-1]+" · 搭配 "+pairs(p)+"/"+COMBOS[g-1]+" · 采样种类 "+CapturedBottles.sampled(p)+"/"+SAMPLES[g-1];}
 public static void advance(ServerPlayer p,String role){int g=grade(p,role);if(!equipped(p,role)||g<1||g>=9)return;boolean ok=role.equals("build")?(discoveries(p)>=DISCOVER[g-1]&&batches(p)>=BATCHES[g-1]&&pairs(p)>=COMBOS[g-1]&&CapturedBottles.sampled(p)>=SAMPLES[g-1]):distinct(p,"made.",role)>=BuildRules.RESEARCH[g-1];if(!ok){CraftSessions.say(p,"任务未完成："+task(p,role));return;}String old="rpgtemplate:"+role+"_grade_"+g,next="rpgtemplate:"+role+"_grade_"+(g+1);var d=CraftState.data(p);d.findTemplate(old).ifPresent(t->{t.setTemplateId(next);t.setLevel(1);t.setXp(0);});if(old.equals(d.loadedTemplateId()))d.setLoadedTemplateId(next);d.setNewestTemplateId(next);SystemDataManager.markDirty(p);CraftSessions.say(p,"职业升至 "+(g+1)+"品，制作加成提升，未自动授予新配方。");}
 public static double maxHp(ServerPlayer p){return CraftState.data(p).isActivated()?StatCalculator.maxStat(StatType.HP,CraftState.data(p),TemplateRegistry.get(),CoreConfig.get()):p.m_21233_();}
 public static void harm(ServerPlayer p,double fraction){if(!p.m_6084_())return;double amount=Math.max(.1,maxHp(p)*fraction);if(com.rpgtemplate.forge.king.KingRules.active(p)){var d=CraftState.data(p);long now=p.m_9236_().m_46467_();amount*=com.rpgtemplate.forge.king.KingRules.defenseDamageScale(com.rpgtemplate.forge.king.KingRules.defense(d,"king.amp",now),com.rpgtemplate.forge.king.KingRules.defense(d,"king.basket",now),false);}if(CraftState.data(p).isActivated()){var d=CraftState.data(p);double hp=d.hp()<0?maxHp(p):d.hp();d.setHp(Math.max(0,hp-amount));SystemDataManager.markDirty(p);if(d.hp()<=0)kill(p);}else{p.m_21153_((float)Math.max(0,p.m_21223_()-amount));if(p.m_21223_()<=0)kill(p);}}
 public static void kill(ServerPlayer p){if(CraftState.data(p).isActivated()){CraftState.data(p).setHp(0);SystemDataManager.markDirty(p);}p.m_21153_(0);p.m_6667_(p.m_269291_().m_269264_());}
 public static void onDeath(ServerPlayer p){BuildCinematics.cancel(p);Enhancers.clear(p);CapturedBottles.end(p,true);var b=body(p);b.m_128347_("load",0);b.m_128347_("pending",0);b.m_128347_("energy",0);BuildBottles.clearTransient(p);MedicalJobs.death(p);}
 public static void tickSecond(ServerPlayer p){ensureProfessions(p);if(!p.m_6084_())return;var b=body(p);int oldLevel=danger(p);var next=BuildRules.second(oldLevel,b.m_128459_("progress"),b.m_128459_("pending"),b.m_128459_("load"));b.m_128405_("danger",next.level());b.m_128347_("progress",next.progress());b.m_128347_("pending",next.pending());b.m_128347_("load",next.load());if(next.level()>oldLevel)CraftSessions.say(p,"危险等级提升至 "+next.level());if(next.load()>100){harm(p,.02);if(!p.m_6084_())return;}b.m_128347_("energy",Math.min(100,b.m_128459_("energy")+2));BuildBottles.passives(p);}
